public static void addToClassPath(Vector<URL> cpV, String dir) {
    URLClassLoader classLoader = (URLClassLoader) Thread.currentThread().getContextClassLoader();
    try {
        URL url = new URL(dir);
        cpV.add(url);
        classLoader.addURL(url);
        System.out.println("Files added to classpath: " + dir);
    } catch (MalformedURLException e) {
        e.printStackTrace();
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File dirFile = new File(dir);
    if (!dirFile.exists()) {
        throw new RuntimeException("Directory does not exist: " + dir);
    }

    File[] files = dirFile.listFiles((file) -> file.isFile() && file.getName().endsWith(".jar"));
    if (files == null) {
        throw new RuntimeException("Failed to list files in " + dir);
    }

    for (File file : files) {
        URL url = null;
        try {
            url = file.toURI().toURL();
            cpV.add(url);
        } catch (MalformedURLException e) {
            throw new RuntimeException("Failed to create file URL for " + file.getAbsolutePath(), e);
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    for (File f : new File(dir).listFiles()) {
        if (f.isDirectory()) continue;
        try {
            cpV.add(f.toURI().toURL());
        } catch (MalformedURLException e) {}
    }
}

