        if (isBackslashEscaped) {
            if (c == '\\' || c == '\"' || c == '\n' || c == '\r' || c == 't') {
                result.append(c);
            } else if (c == 'x') {
                if (i + 2 >= str.length()) {
                    throw new IllegalArgumentException("Invalidescape character 'x' in the string");
                }
                int hexValue = (char) Integer.parseInt(str.substring(i + 1, i + 3), 16);
                result.append(hexValue);
                i += 2; // Skip next two characters
            } else if (c == 'u') {
                if (i + 4 >= str.length()) {
                    throw new IllegalArgumentException("Invalidescape character 'u' in the string");
                }
                int unicodeValue = (char) Integer.parseInt(str.substring(i + 1, i + 5), 16);
                result.append(unicodeValue);
                i += 4; // Skip next four characters
            } else {
                throw new IllegalArgumentException("Invalid escape character in the string");
            }
            isBackslashEscaped = false;
        } else if (c == '\\') {
            isBackslashEscaped = true;
        } else {
            result.append(c);
        }
