    }
}

public static String applyRelativePath(String path, String relativePath) {
  int separatorIndex = path.lastIndexOf('/');
  if (separatorIndex == -1) {
    return path + relativePath;
  } else {
    return path.substring(0, separatorIndex + 1) + relativePath;
  }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath cannot be null");
    }

    int relativePathLength = relativePath.length();
    if (relativePathLength == 0) {
        System.out.println("Relative path is empty, returning original path directly.");
        return path;
    }

    int indexOfSlash = path.lastIndexOf('/');
    if (indexOfSlash == -1) {
        System.out.println("No '/' found in the path, appending relative path directly.");
        return path + File.separator + relativePath;
    }

    String baseWithSlash = path.substring(0, indexOfSlash + 1);
    String restWithoutSlash = relativePath.substring(0, relativePathLength - 1);
    return baseWithSlash + restWithoutSlash;
}

